/bin/zsh -lc "npm test
node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { qualifiesForFreeShipping } from './src/shipping.js';
import { discountCents } from './src/discount.js';
for (let cents = 0; cents <= 20000; cents++) {
  assert.equal(qualifiesForFreeShipping(cents), cents > 4999);
  assert.equal(discountCents(cents), cents > 9999 ? 500 : 0);
}
for (const cents of [1000000, Number.MAX_SAFE_INTEGER]) {
  assert.equal(qualifiesForFreeShipping(cents), true);
  assert.equal(discountCents(cents), 500);
}
console.log('Verified 20,001 integer subtotals and two large safe integers for both exports.');
JS
cat src/shipping.js src/discount.js test/shipping.test.js test/discount.test.js docs/specs/2026-10-04-shipping.md docs/specs/2026-10-04-shipping-slices.md"

